from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_CENT = Decimal("0.01")
_Q4 = Decimal("0.0001")


def _quantize_to(value, target):
    t_exp = target.as_tuple().exponent
    if not value.is_finite():
        with localcontext() as ctx:
            ctx.prec = 60
            return value.quantize(target, rounding=ROUND_HALF_UP)
    if value.is_zero():
        with localcontext() as ctx:
            ctx.prec = 60
            return value.quantize(target, rounding=ROUND_HALF_UP)
    adj = value.adjusted()
    digits = len(value.as_tuple().digits)
    need_q = adj - t_exp + 1
    if need_q < digits:
        need_q = digits
    need_q += 10
    if need_q < 60:
        need_q = 60
    with localcontext() as ctx:
        ctx.prec = need_q
        return value.quantize(target, rounding=ROUND_HALF_UP)


def _d2(value):
    return _quantize_to(value, _CENT)


def _q4(value):
    return _quantize_to(value, _Q4)


def _div50(a, b):
    with localcontext() as ctx:
        ctx.prec = 50
        return a / b


def _cents_mul(a, qty_int):
    a_digits = len(a.as_tuple().digits)
    q_digits = len(str(abs(qty_int))) if qty_int != 0 else 1
    need_prod = max(a_digits + q_digits + 10, 60)
    with localcontext() as ctx:
        ctx.prec = need_prod
        prod = a * qty_int
    return _quantize_to(prod, _CENT)


def _sum_need(a, b, target_exp):
    adjs = []
    exps = []
    for v in (a, b):
        if not v.is_zero():
            try:
                adjs.append(v.adjusted())
            except Exception:
                pass
            exps.append(v.as_tuple().exponent)
    if not adjs:
        return 60
    max_adj = max(adjs)
    min_exp = min(exps) if exps else target_exp
    if min_exp > target_exp:
        min_exp = target_exp
    # for exact sum before quantize we need down to min_exp
    need = max_adj - min_exp + 1
    need = max(need, len(a.as_tuple().digits), len(b.as_tuple().digits)) + 10
    if need < 60:
        need = 60
    return need


def _cents_add(a, b):
    need = _sum_need(a, b, -2)
    with localcontext() as ctx:
        ctx.prec = need
        s = a + b
    return _quantize_to(s, _CENT)


def _cents_sub(a, b):
    need = _sum_need(a, b, -2)
    with localcontext() as ctx:
        ctx.prec = need
        s = a - b
    return _quantize_to(s, _CENT)


def process_inventory(movements: list[dict]) -> dict:
    if not isinstance(movements, list):
        raise ValueError("movements must be a list")
    qty = 0
    value = Decimal("0.00")
    total_cogs = Decimal("0.00")
    total_pr = Decimal("0.00")
    for mv in movements:
        if not isinstance(mv, dict):
            raise ValueError("movement must be a dict")
        mtype = mv.get("type")
        if mtype not in ("PURCHASE", "SALE", "CUSTOMER_RETURN", "PURCHASE_RETURN"):
            raise ValueError(f"invalid movement type: {mtype!r}")
        quantity = mv.get("quantity")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("quantity must be a positive int")
        if mtype == "PURCHASE":
            if "unit_cost" not in mv:
                raise ValueError("unit_cost required for PURCHASE")
            raw = mv["unit_cost"]
            if not isinstance(raw, str):
                raise ValueError("unit_cost must be a string")
            try:
                cost = Decimal(raw)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid unit_cost: {raw!r}") from None
            if not cost.is_finite() or cost < 0:
                raise ValueError("unit_cost must be finite and >= 0")
            added = _cents_mul(cost, quantity)
            value = _cents_add(value, added)
            qty += quantity
        elif mtype == "SALE":
            if quantity > qty:
                raise ValueError("sale exceeds quantity on hand")
            avg = _div50(value, qty)
            cogs = _cents_mul(avg, quantity)
            value = _cents_sub(value, cogs)
            qty -= quantity
            total_cogs = _cents_add(total_cogs, cogs)
        elif mtype == "CUSTOMER_RETURN":
            if qty == 0:
                raise ValueError("no current average cost for customer return")
            avg = _div50(value, qty)
            added = _cents_mul(avg, quantity)
            value = _cents_add(value, added)
            qty += quantity
        else:  # PURCHASE_RETURN
            if quantity > qty:
                raise ValueError("purchase return exceeds quantity on hand")
            avg = _div50(value, qty)
            removed = _cents_mul(avg, quantity)
            value = _cents_sub(value, removed)
            qty -= quantity
            total_pr = _cents_add(total_pr, removed)
    if qty == 0:
        avg_out = Decimal("0.0000")
    else:
        avg_raw = _div50(value, qty)
        avg_out = _q4(avg_raw)
    return {
        "quantity_on_hand": qty,
        "inventory_value": _d2(value),
        "average_cost": avg_out,
        "total_cogs": _d2(total_cogs),
        "total_purchase_returns": _d2(total_pr),
    }
